package com.studenthub.controller;
import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.util.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.nio.file.*;
@WebServlet(name="PrivateAttachmentServlet",urlPatterns="/messages/attachments/*")
public class PrivateAttachmentServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();private final AttachmentStorage storage=new AttachmentStorage();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=q.getPathInfo();if(p==null||!p.matches("/\\d+")){r.sendError(404);return;}var a=dao.attachment(Long.parseLong(p.substring(1)),(Long)q.getSession().getAttribute("userId")).orElse(null);if(a==null){r.sendError(404);return;}Path file=storage.find(a.storageKey()).orElse(null);if(file==null){r.sendError(404);return;}r.setContentType(a.mimeType());r.setHeader("X-Content-Type-Options","nosniff");r.setHeader("Cache-Control","private, max-age=3600");r.setHeader("Content-Disposition",(a.isImage()||a.isVideo()?"inline":"attachment")+"; filename*=UTF-8''"+java.net.URLEncoder.encode(a.originalFilename(),java.nio.charset.StandardCharsets.UTF_8).replace("+","%20"));Files.copy(file,r.getOutputStream());}catch(Exception e){r.sendError(404);}}}
